#requires -Version 7.0
param(
  [Parameter(Mandatory=$true)][ValidateSet('Execute','Reconcile')][string]$Mode,
  [Parameter(Mandatory=$true)][string]$ExportPath,
  [Parameter(Mandatory=$true)][string]$BundlePath,
  [Parameter(Mandatory=$true)][ValidatePattern('^[a-f0-9]{64}$')][string]$BundleSha256,
  [string]$AttemptPath,
  [string]$AttemptSha256
)
$ErrorActionPreference='Stop'
try {
  if($PSVersionTable.PSVersion.Major -lt 7){throw 'PowerShell 7 required'}
  $values=@()
  foreach($line in [IO.File]::ReadAllLines([IO.Path]::GetFullPath($ExportPath))){
    if($line -match '^\s*(?:export\s+)?DATABASE_URL\s*=\s*(.*?)\s*$'){
      $value=$Matches[1]
      if($value.StartsWith('"')){$value=ConvertFrom-Json $value}
      elseif($value.StartsWith("'") -and $value.EndsWith("'")){$value=$value.Substring(1,$value.Length-2)}
      $values+=$value
    }elseif($line -match '^\s*"DATABASE_URL"\s*:\s*("(?:[^"\\]|\\.)*")\s*,?\s*$'){$values+=(ConvertFrom-Json $Matches[1])}
  }
  if($values.Count -ne 1){throw 'exact DATABASE_URL required'}
  $uri=[Uri]$values[0];$user=$uri.UserInfo.Split(':',2)
  if($uri.Scheme -notin @('postgres','postgresql') -or $uri.Host -ne 'aws-1-us-west-1.pooler.supabase.com' -or $uri.Port -ne 5432 -or $uri.AbsolutePath -ne '/postgres' -or [Uri]::UnescapeDataString($user[0]) -ne 'postgres.icockcoguyadhryzydvl' -or $user.Count -ne 2 -or -not $user[1]){throw 'fixed database target required'}

  $root=[IO.Path]::GetFullPath('.')
  if([IO.Path]::IsPathRooted($BundlePath) -or $BundlePath.Contains('\') -or $BundlePath.Split('/') -contains '..' -or -not $BundlePath.StartsWith('.superpowers/m80-foundation-executor-') -or -not $BundlePath.EndsWith('.json')){throw 'fixed executor bundle path required'}
  $bundleFull=[IO.Path]::GetFullPath($BundlePath)
  if(-not $bundleFull.StartsWith($root+[IO.Path]::DirectorySeparatorChar)){throw 'bundle escaped workspace'}
  $actualBundle=([BitConverter]::ToString([Security.Cryptography.SHA256]::HashData([IO.File]::ReadAllBytes($bundleFull)))).Replace('-','').ToLowerInvariant()
  if($actualBundle -ne $BundleSha256){throw 'bundle bytes changed'}

  $attempt=$null
  if($Mode -eq 'Execute'){
    if($AttemptPath -or $AttemptSha256){throw 'new execution refuses prior attempt'}
  }else{
    if(-not $AttemptPath -or $AttemptSha256 -notmatch '^[a-f0-9]{64}$' -or [IO.Path]::IsPathRooted($AttemptPath) -or $AttemptPath.Contains('\') -or $AttemptPath.Split('/') -contains '..' -or -not $AttemptPath.StartsWith('.superpowers/m80-foundation-executor-') -or -not $AttemptPath.EndsWith('-attempt.json')){throw 'exact reconciliation attempt required'}
    $attemptFull=[IO.Path]::GetFullPath($AttemptPath)
    if(-not $attemptFull.StartsWith($root+[IO.Path]::DirectorySeparatorChar)){throw 'attempt escaped workspace'}
    $actualAttempt=([BitConverter]::ToString([Security.Cryptography.SHA256]::HashData([IO.File]::ReadAllBytes($attemptFull)))).Replace('-','').ToLowerInvariant()
    if($actualAttempt -ne $AttemptSha256){throw 'attempt bytes changed'}
    $attempt=[ordered]@{path=$AttemptPath;sha256=$AttemptSha256}
  }

  $input=[ordered]@{profile='neuvetra.m80.foundation-executor-private-input.v1';operatorId='/root';mode=$Mode.ToLowerInvariant();bundle=[ordered]@{path=$BundlePath;sha256=$BundleSha256};attempt=$attempt;operatorDatabaseUrl=$values[0];railwaySessionMode='current_authenticated_cli'}
  $entry=[IO.Path]::GetFullPath('.superpowers/m80-foundation-executor.ts')
  $start=[Diagnostics.ProcessStartInfo]::new();$start.FileName=(Get-Command bun).Source;$start.UseShellExecute=$false;$start.CreateNoWindow=$true;$start.RedirectStandardInput=$true;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true
  $start.ArgumentList.Add('run');$start.ArgumentList.Add($entry)
  $process=[Diagnostics.Process]::Start($start);$stdout=$process.StandardOutput.ReadToEndAsync();$stderr=$process.StandardError.ReadToEndAsync()
  $process.StandardInput.Write(($input|ConvertTo-Json -Compress -Depth 5));$process.StandardInput.Close();$process.WaitForExit()
  if($process.ExitCode -ne 0){throw 'private executor refused or outcome uncertain'}
  [Console]::Out.Write($stdout.Result)
}catch{
  [Console]::Out.Write('{"status":"m80_foundation_executor_private_bridge_refused_or_uncertain","retryAllowed":false}')
  exit 1
}

