async function localImportClosure(roots: readonly string[]): Promise<string[]> {
  const pending = [...roots]
  const found = new Set<string>()
  while (pending.length) {
    const path = pending.pop()!.replaceAll("\\", "/")
    if (found.has(path)) continue
    const bytes = await readFile(path)
    found.add(path)
    if (!/\.[cm]?[jt]sx?$/.test(path)) continue
    const text = bytes.toString("utf8")
    const imports = [...text.matchAll(/(?:import|export)\s+(?:type\s+)?(?:[^"']*?\sfrom\s*)?["'](\.{1,2}\/[^"']+)["']/g)].map(match => match[1]!)
    for (const specifier of imports) {
      const base = resolve(dirname(path), specifier)
      const candidates = /\.[cm]?[jt]sx?$/.test(base) ? [base] : [`${base}.ts`, `${base}.tsx`, `${base}/index.ts`]
      let resolved: string | undefined
      for (const candidate of candidates) {
        try { await readFile(candidate); resolved = relative(resolve("."), candidate).replaceAll("\\", "/"); break } catch {}
      }
      check(!!resolved, `Local source closure import is unresolved: ${path} -> ${specifier}`)
      pending.push(resolved)
    }
  }
  return [...found].sort()
}

export async function helperPins() {
