      "text": "import { afterEach, describe, expect, test } from \"bun:test\"\nimport { mkdtemp, open, readFile, rm } from \"node:fs/promises\"\nimport { tmpdir } from \"node:os\"\nimport { join } from \"node:path\"\nimport {\n  M80_ACCEPTED_CANDIDATE_SHA256,\n  M80_HOSTED_INPUT_PROFILE,\n  M80_MIGRATION_0022_SHA256,\n  M80_EXPECTED_NEW_TABLE_ROW_COUNTS,\n  M80_NEW_TABLES,\n  M80_REQUIRED_CHECKS,\n  M80_RUNTIME_ROOT_CLOSURE_SHA256,\n  buildM80HostedPreparationPlan,\n  m80ExpectedHostedEvidence,\n  m80HostedCanonicalJson,\n  m80HostedSha256,\n  safeM80HostedPreparationOutputPath,\n  type EvidencePin,\n  type HostedPreparationInput,\n  type M80HostedPreparationPlan,\n} from \"./m80-foundation-hosted-prepare\"\nimport {\n  M80_HOSTED_GATE_PROFILE,\n  M80_HOSTED_OBSERVATION_PROFILE,\n  m80HostedIntentPath,\n  recordM80HostedOutcome,\n  sealM80HostedIntent,\n  validateM80HostedPlan,\n  writeM80HostedEvidenceOnce,\n  type M80HostedIntent,\n  type M80HostedOutcome,\n  type M80HostedStage,\n} from \"./m80-foundation-hosted-once\"\n\nconst NOW = new Date(\"2026-09-24T22:12:00.000Z\")\nconst sha = (character: string) => character.repeat(64)\nconst fakePin = (path: string, character: string): EvidencePin => ({ path, sha256: sha(character) })\nconst artifactSha256 = (value: unknown) => m80HostedSha256(`${JSON.stringify(value, null, 2)}\\n`)\nconst artifactPin = (path: string, value: unknown): EvidencePin => ({ path, sha256: artifactSha256(value) })\nconst OBSERVED_TABLES = [\"auth.users\", \"neuvetra.companies\", \"neuvetra.company_members\"]\nconst OBSERVED_TABLES_SHA256 = m80HostedSha256(m80HostedCanonicalJson(OBSERVED_TABLES))\nconst temporary: string[] = []\n\nafterEach(async () => {\n  while (temporary.length) await rm(temporary.pop()!, { recursive: true, force: true })\n})\n\nfunction input(): HostedPreparationInput {\n  const value: HostedPreparationInput = {\n    profile: M80_HOSTED_INPUT_PROFILE,\n    operatorId: \"/root\",\n    observedTarget: {\n      observedAt: \"2026-09-24T22:10:00.000Z\",\n      observationReceipt: fakePin(\".superpowers/m80-foundation-hosted-target-observation.json\", \"0\"),\n      projectRef: \"abcdefghijklmnopqrst\",\n      environmentId: \"80000000-0000-4000-8000-000000000001\",\n      serviceId: \"80000000-0000-4000-8000-000000000002\",\n      deploymentId: \"80000000-0000-4000-8000-000000000003\",\n      deploymentStatus: \"SUCCESS\",\n      deployedCommitSha: \"1\".repeat(40),\n      deployedImageSha256: sha(\"2\"),\n      targetClassification: \"private_synthetic_staging\",\n      syntheticDataOnlyVerified: true,\n      schemaVersion: 21,\n      migrationReceiptCount: 21,\n      observedNonReceiptTableCount: 3,\n      observedNonReceiptTables: [...OBSERVED_TABLES],\n      historicalReferenceNonReceiptTableCount: 120,\n      applicationReadinessSchemaVersion: 21,\n      applicationStateSha256: sha(\"3\"),\n      automaticDeploymentsPaused: true,\n      writeQuiescenceRequiredBeforeExecution: true,\n    },\n    publication: {\n      reviewedHeadCommitSha: \"4\".repeat(40),\n      headObservedAt: \"2026-09-24T22:11:00.000Z\",\n      checksObservedAt: \"2026-09-24T22:11:00.000Z\",\n      requiredChecks: M80_REQUIRED_CHECKS.map(name => ({ name, status: \"completed\", conclusion: \"success\" })),\n      publicationReviewVerdict: \"pass\",\n      publicationReview: fakePin(\"evaluations/research-qa/m80-publication-review.json\", \"4\"),\n      integrationAcceptanceVerdict: \"pass\",\n      integrationAcceptance: fakePin(\"evaluations/research-qa/m80-integration-acceptance.json\", \"5\"),\n    },\n    acceptedRuntime: {\n      candidate: { path: \"operations/agent-improvement/snapshots/M80-FOUNDATION-RUNTIME-20260924-CANDIDATE2.json\", sha256: M80_ACCEPTED_CANDIDATE_SHA256 },\n      migration: { path: \"packages/neuvetra-database/src/migrations/0022_scope1_beta_foundation.sql\", sha256: M80_MIGRATION_0022_SHA256 },\n      rootClosure: { path: \"evaluations/research-qa/m80-foundation-runtime-root-closure-20260924.json\", sha256: M80_RUNTIME_ROOT_CLOSURE_SHA256 },\n    },\n    backup: {\n      completedAt: \"2026-09-24T22:00:00.000Z\",\n      sourceSchemaVersion: 21,\n      sourceApplicationStateSha256: sha(\"3\"),\n      applicationOnly: true,\n      syntheticDataOnly: true,\n      providerRecoveryExcluded: true,\n      backupReceipt: fakePin(\".superpowers/m80-foundation-hosted-backup-receipt.json\", \"6\"),\n      encryptedArchiveSha256: sha(\"7\"), snapshotSha256: sha(\"8\"), customDumpSha256: sha(\"9\"),\n    },\n    rehearsal: {\n      completedAt: \"2026-09-24T22:05:00.000Z\",\n      disposableDatabaseName: \"m80_ops_foundation_1790287200\",\n      hostedEvidence: false,\n      sourceSchemaVersion: 21,\n      targetSchemaVersion: 22,\n      sourceBackupReceiptSha256: sha(\"6\"),\n      migrationSha256: M80_MIGRATION_0022_SHA256,\n      sourceObservedNonReceiptTableCount: 3,\n      sourceObservedNonReceiptTablesSha256: OBSERVED_TABLES_SHA256,\n      historicalReferenceNonReceiptTableCount: 120,\n      oldMigrationReceiptCount: 21,\n      sourceContentSha256: sha(\"a\"), restoredContentSha256: sha(\"a\"),\n      sourceMetadataSha256: sha(\"b\"), restoredMetadataSha256: sha(\"b\"),\n      oldContentExact: true, oldMetadataExact: true,\n      expectedNewTables: [...M80_NEW_TABLES],\n      expectedNewTableRowCounts: { ...M80_EXPECTED_NEW_TABLE_ROW_COUNTS },\n      releaseRecordsExactFourHeld: true,\n      forcedRlsVerified: true, runtimeSelectOnlyVerified: true, runtimeDirectWritesDenied: true,\n      operatorAdmissionNotExecuted: true, allConnectionsClosed: true,\n      restoreReceipt: fakePin(\"evaluations/research-qa/m80-hosted-restore.json\", \"a\"),\n      preservationReceipt: fakePin(\"evaluations/research-qa/m80-hosted-preservation.json\", \"b\"),\n      migrationReceipt: fakePin(\"evaluations/research-qa/m80-hosted-rehearsal.json\", \"c\"),\n    },\n    admission: {\n      verifiedAt: \"2026-09-24T22:11:00.000Z\",\n      observationReceipt: fakePin(\".superpowers/m80-foundation-hosted-admission-observation.json\", \"f\"),\n      companyId: \"80000000-0000-4000-8000-000000000101\",\n      managerUserId: \"80000000-0000-4000-8000-000000000102\",\n      managerRole: \"owner\",\n      existingSyntheticCompanyVerified: true, existingManagerMembershipVerified: true,\n      noCompanyCreation: true, noUserCreation: true, noRoleOrPermissionCreation: true,\n    },\n  }\n  const integration = m80ExpectedHostedEvidence(value, \"integration\")\n  value.publication.integrationAcceptance.sha256 = artifactSha256(integration)\n  return value\n}\n\nfunction semanticEvidence(value: HostedPreparationInput): Map<string, unknown> {\n  return new Map([\n    [value.observedTarget.observationReceipt.path, m80ExpectedHostedEvidence(value, \"target\")],\n    [value.publication.publicationReview.path, m80ExpectedHostedEvidence(value, \"publication\")],\n    [value.publication.integrationAcceptance.path, m80ExpectedHostedEvidence(value, \"integration\")],\n    [value.backup.backupReceipt.path, m80ExpectedHostedEvidence(value, \"backup\")],\n    [value.rehearsal.restoreReceipt.path, m80ExpectedHostedEvidence(value, \"restore\")],\n    [value.rehearsal.preservationReceipt.path, m80ExpectedHostedEvidence(value, \"preservation\")],\n    [value.rehearsal.migrationReceipt.path, m80ExpectedHostedEvidence(value, \"rehearsal\")],\n    [value.admission.observationReceipt.path, m80ExpectedHostedEvidence(value, \"admission\")],\n  ])\n}\n\nfunction build(value: unknown, now = NOW, checked?: string[]) {\n  const candidate = value as HostedPreparationInput\n  const semantic = semanticEvidence(candidate)\n  return buildM80HostedPreparationPlan(value, {\n    now,\n    verifyPin: async item => { checked?.push(item.path) },\n    loadJsonEvidence: async item => {\n      const evidence = semantic.get(item.path)\n      if (!evidence) throw new Error(`missing evidence fixture ${item.path}`)\n      return evidence\n    },\n  })\n}\n\ntype GateBundle = { gate: Record<string, unknown>; gatePin: EvidencePin; gateEvidence: { securityReview: { value: unknown; pin: EvidencePin }; integrationAcceptance: { value: unknown; pin: EvidencePin }; targetObservation: { value: unknown; pin: EvidencePin } } }\n\nfunction gateBundle(plan: M80HostedPreparationPlan, planPin: EvidencePin, stage: M80HostedStage, reviewedAt = NOW.toISOString()): GateBundle {\n  const integration = m80ExpectedHostedEvidence({ profile: M80_HOSTED_INPUT_PROFILE, operatorId: \"/root\", observedTarget: plan.target, publication: plan.publication, acceptedRuntime: { candidate: plan.pins.candidate, migration: plan.pins.migration, rootClosure: plan.pins.rootClosure }, backup: plan.backup, rehearsal: plan.rehearsal, admission: plan.admission } as HostedPreparationInput, \"integration\")\n  const target = { profile: \"neuvetra.m80.foundation-hosted-stage-target-observation.v1\", observedAt: reviewedAt, stage, projectRef: plan.target.projectRef, environmentId: plan.target.environmentId, serviceId: plan.target.serviceId, schemaVersion: stage === \"migration\" ? 21 : 22, migrationReceiptCount: stage === \"migration\" ? 21 : 22, applicationStateSha256: stage === \"migration\" ? plan.target.applicationStateSha256 : sha(\"d\"), writeQuiescenceMechanism: \"provider_deployment_stopped_and_origin_readiness_unavailable\", activeDeploymentCount: 0, originReadinessUnavailable: true, noActiveApplicationWritesObserved: true }\n  const integrationPin = artifactPin(plan.pins.integrationAcceptance.path, integration)\n  const targetPin = artifactPin(`.superpowers/m80-foundation-hosted-${stage}-target.json`, target)\n  const securityPath = `evaluations/research-qa/m80-hosted-preparation-${stage}-security.json`\n  const security = { profile: \"neuvetra.m80.foundation-hosted-security-review.v1\", observedAt: reviewedAt, verdict: \"pass\", reviewerId: \"/root/m80_foundation_hosted_qa\", implementationAuthor: \"/root/m80_foundation_runtime\", independent: true, plan: planPin, planSha256: plan.planSha256, operationScopeSha256: plan.operationScopeSha256, stage, targetProjectRef: plan.target.projectRef, reviewedHeadCommitSha: plan.publication.reviewedHeadCommitSha, candidateSha256: M80_ACCEPTED_CANDIDATE_SHA256, migrationSha256: M80_MIGRATION_0022_SHA256, materialFindingsOpen: 0 }\n  const securityPin = artifactPin(securityPath, security)\n  const gate = {\n    profile: M80_HOSTED_GATE_PROFILE, stage, reviewedAt, expiresAt: \"2026-09-24T22:22:00.000Z\", verdict: \"pass\", operatorId: \"/root\", independentReviewerId: \"/root/m80_foundation_hosted_qa\",\n    plan: planPin, planSha256: plan.planSha256, candidateSha256: M80_ACCEPTED_CANDIDATE_SHA256, migrationSha256: M80_MIGRATION_0022_SHA256,\n    reviewedHeadCommitSha: plan.publication.reviewedHeadCommitSha, exactRequiredChecksPassed: true,\n    targetObservation: targetPin, targetReobservedAt: reviewedAt, targetProjectRef: plan.target.projectRef, targetEnvironmentId: plan.target.environmentId, targetServiceId: plan.target.serviceId,\n    currentSchemaVersion: stage === \"migration\" ? 21 : 22, currentMigrationReceiptCount: stage === \"migration\" ? 21 : 22,\n    currentApplicationStateSha256: stage === \"migration\" ? plan.target.applicationStateSha256 : sha(\"d\"), writeQuiescenceMechanism: \"provider_deployment_stopped_and_origin_readiness_unavailable\", activeDeploymentCount: 0, originReadinessUnavailable: true, noActiveApplicationWritesObserved: true,\n    securityReview: securityPin, integrationAcceptance: integrationPin, rootSoleExecutorAccepted: true, noAutomaticRetryAccepted: true,\n  }\n  return { gate, gatePin: artifactPin(`.superpowers/m80-foundation-hosted-${stage}-gate.json`, gate), gateEvidence: { securityReview: { value: security, pin: securityPin }, integrationAcceptance: { value: integration, pin: integrationPin }, targetObservation: { value: target, pin: targetPin } } }\n}\n\ntype Sealed = GateBundle & { intent: M80HostedIntent }\nfunction seal(plan: M80HostedPreparationPlan, planPin: EvidencePin, stage: M80HostedStage, predecessors: Pick<Parameters<typeof sealM80HostedIntent>[0], \"migration\" | \"admission\"> = {}): Sealed {\n  const bundle = gateBundle(plan, planPin, stage)\n  return { ...bundle, intent: sealM80HostedIntent({ plan, planPin, stage, now: NOW, ...bundle, ...predecessors }) }\n}\n\nfunction observation(intent: M80HostedIntent, transportOutcome: \"definitive_success\" | \"definitive_failure\" | \"unknown\" = \"definitive_success\", observedAt = NOW.toISOString()) {\n  const authoritativeState = transportOutcome !== \"definitive_success\" ? {} : intent.stage === \"migration\"\n    ? { projectRef: intent.targetProjectRef, environmentId: intent.targetEnvironmentId, serviceId: intent.targetServiceId, schemaVersion: 22, migrationReceiptCount: 22, migrationName: \"0022_scope1_beta_foundation.sql\", migrationSha256: M80_MIGRATION_0022_SHA256, oldContentExact: true, oldMetadataExact: true }\n    : intent.stage === \"admission\"\n      ? { projectRef: intent.targetProjectRef, environmentId: intent.targetEnvironmentId, serviceId: intent.targetServiceId, rowCount: 1, companyId: intent.actionIdentity.companyId, managerUserId: intent.actionIdentity.managerUserId, fixtureProfileId: \"m80-synthetic-scope1-foundation-v1\", fixtureVersion: 1, fixtureSha256: intent.actionIdentity.fixtureSha256 }\n      : { projectRef: intent.targetProjectRef, environmentId: intent.actionIdentity.environmentId, serviceId: intent.actionIdentity.serviceId, deploymentStatus: \"SUCCESS\", deploymentId: \"80000000-0000-4000-8000-000000000009\", commitSha: intent.actionIdentity.commitSha, schemaVersion: 22, readinessOk: true }\n  return { profile: M80_HOSTED_OBSERVATION_PROFILE, observedAt, stage: intent.stage, transportOutcome, authoritativeState }\n}\n\nfunction record(sealed: Sealed, value = observation(sealed.intent)): Sealed & { intentPin: EvidencePin; observation: unknown; observationPin: EvidencePin; outcome: M80HostedOutcome; outcomePin: EvidencePin } {\n  const intent = sealed.intent\n  const intentPin = artifactPin(m80HostedIntentPath(intent, intent.stage), intent)\n  const observationPin = artifactPin(`.superpowers/m80-foundation-hosted-${intent.operationScopeSha256}-${intent.stage}-observation.json`, value)\n  const outcome = recordM80HostedOutcome({ intent, intentPin, observation: value, observationPin, now: NOW })\n  return { ...sealed, intentPin, observation: value, observationPin, outcome, outcomePin: artifactPin(`.superpowers/m80-foundation-hosted-${intent.operationScopeSha256}-${intent.stage}-outcome.json`, outcome) }\n}\n\nconst chainArgs = (name: \"migration\" | \"admission\", chain: ReturnType<typeof record>) => ({ [name]: { intent: chain.intent, intentPin: chain.intentPin, gate: chain.gate, gatePin: chain.gatePin, gateEvidence: chain.gateEvidence, observation: chain.observation, observationPin: chain.observationPin, outcome: chain.outcome, outcomePin: chain.outcomePin } })\n\nfunction resignPlan(plan: M80HostedPreparationPlan): M80HostedPreparationPlan {\n  const unsigned = structuredClone(plan) as M80HostedPreparationPlan & { planSha256?: string }\n  delete unsigned.planSha256\n  return { ...unsigned, planSha256: m80HostedSha256(m80HostedCanonicalJson(unsigned)) } as M80HostedPreparationPlan\n}\n\nfunction promoteOutcome(chain: ReturnType<typeof record>): ReturnType<typeof record> {\n  const unsigned = { ...structuredClone(chain.outcome), status: \"verified_success\", nextActionAllowed: true } as Record<string, unknown>\n  delete unsigned.outcomeSha256\n  const outcome = { ...unsigned, outcomeSha256: m80HostedSha256(m80HostedCanonicalJson(unsigned)) } as unknown as M80HostedOutcome\n  return { ...chain, outcome, outcomePin: artifactPin(chain.outcomePin.path, outcome) }\n}\n\ndescribe(\"M80 offline hosted preparation evidence\", () => {\n  test(\"builds an unauthorized exact three-stage plan from typed pinned evidence\", async () => {\n    const checked: string[] = [], plan = await build(input(), NOW, checked)\n    expect(checked).toHaveLength(11)\n    expect(plan).toMatchObject({ executionAuthorized: false, noNetworkOrHostedActionPerformed: true, sequence: [\"migration\", \"admission\", \"deployment\"] })\n    expect(plan.actions.admission.sql).toContain(\"where c.id=$1::uuid and m.user_id=$2::uuid\")\n    expect(m80HostedIntentPath(plan, \"migration\")).toContain(plan.operationScopeSha256)\n  })\n\n  test(\"fails closed for stale, secret, pin, check, preservation and scalar-shape changes\", async () => {\n    const stale = input(); stale.observedTarget.observedAt = \"2026-09-24T21:00:00.000Z\"; await expect(build(stale)).rejects.toThrow(\"stale\")\n    const secret = input() as any; secret.databaseUrl = \"postgresql://example\"; await expect(build(secret)).rejects.toThrow(\"Secret-shaped\")\n    const changed = input(); changed.acceptedRuntime.migration.sha256 = sha(\"f\"); await expect(build(changed)).rejects.toThrow(\"pin changed\")\n    const checks = input(); checks.publication.requiredChecks.pop(); await expect(build(checks)).rejects.toThrow(\"exact six\")\n    const preservation = input(); preservation.rehearsal.oldMetadataExact = false as true; await expect(build(preservation)).rejects.toThrow(\"preservation rehearsal\")\n    for (const mutate of [\n      (x: any) => { x.observedTarget.observedAt = [x.observedTarget.observedAt] },\n      (x: any) => { x.publication.headObservedAt = [x.publication.headObservedAt] },\n      (x: any) => { x.publication.checksObservedAt = [x.publication.checksObservedAt] },\n      (x: any) => { x.backup.completedAt = [x.backup.completedAt] },\n      (x: any) => { x.rehearsal.completedAt = [x.rehearsal.completedAt] },\n      (x: any) => { x.admission.verifiedAt = [x.admission.verifiedAt] },\n      (x: any) => { x.admission.managerRole = [x.admission.managerRole] },\n    ]) { const malformed: any = input(); mutate(malformed); await expect(build(malformed)).rejects.toThrow() }\n  })\n\n  test(\"rejects contradictory receipt contents and output path escapes\", async () => {\n    const value = input(), semantic = semanticEvidence(value)\n    semantic.set(value.rehearsal.preservationReceipt.path, { verdict: \"fail\", oldContentExact: false })\n    await expect(buildM80HostedPreparationPlan(value, { now: NOW, verifyPin: async () => {}, loadJsonEvidence: async item => semantic.get(item.path) })).rejects.toThrow(\"contradicts\")\n    expect(() => safeM80HostedPreparationOutputPath(\".superpowers/m80-foundation-hosted-unused/../../evaluations/escape.json\")).toThrow(\"Output\")\n    expect(() => safeM80HostedPreparationOutputPath(\".superpowers\\\\m80-foundation-hosted-escape.json\")).toThrow(\"Output\")\n  })\n\n  test(\"deep-validates rehashed plan facts and action bindings\", async () => {\n    const original = await build(input())\n    const mutations = [\n      (p: any) => { p.publication.requiredChecks[1].name = p.publication.requiredChecks[0].name },\n      (p: any) => { p.target.syntheticDataOnlyVerified = false },\n      (p: any) => { p.rehearsal.oldContentExact = false },\n      (p: any) => { p.actions.admission.companyId = \"80000000-0000-4000-8000-000000000999\" },\n      (p: any) => { p.actions.deployment.serviceId = \"80000000-0000-4000-8000-000000000999\" },\n      (p: any) => { p.rehearsal.expectedNewTables[0] = [p.rehearsal.expectedNewTables[0]] },\n      (p: any) => { p.rehearsal.expectedNewTableRowCounts.scope1_beta_release_records = 0 },\n      (p: any) => { p.rehearsal.releaseRecordsExactFourHeld = false },\n      (p: any) => { p.sequence[0] = [p.sequence[0]] },\n    ]\n    for (const mutate of mutations) { const plan: any = structuredClone(original); mutate(plan); expect(() => validateM80HostedPlan(resignPlan(plan), NOW)).toThrow() }\n  })\n\n  test(\"requires actual independent gate evidence bytes bound to the exact stage\", async () => {\n    const plan = await build(input()), planPin = artifactPin(\".superpowers/m80-foundation-hosted-plan.json\", plan), bundle = gateBundle(plan, planPin, \"migration\")\n    const missing = structuredClone(bundle.gateEvidence); missing.securityReview.value = { verdict: \"pass\" }\n    expect(() => sealM80HostedIntent({ plan, planPin, stage: \"migration\", now: NOW, gate: bundle.gate, gatePin: bundle.gatePin, gateEvidence: missing })).toThrow(\"evidence bytes\")\n    const selfReviewed = structuredClone(bundle.gate); selfReviewed.independentReviewerId = \"/root\"\n    expect(() => sealM80HostedIntent({ plan, planPin, stage: \"migration\", now: NOW, gate: selfReviewed, gatePin: artifactPin(\".superpowers/m80-foundation-hosted-gate.json\", selfReviewed), gateEvidence: bundle.gateEvidence })).toThrow(\"independent\")\n  })\n\n  test(\"seals only complete same-plan predecessor chains in migration, admission, deployment order\", async () => {\n    const plan = await build(input()), planPin = artifactPin(\".superpowers/m80-foundation-hosted-plan.json\", plan)\n    const migration = record(seal(plan, planPin, \"migration\"))\n    expect(() => seal(plan, planPin, \"admission\")).toThrow(\"chain required\")\n    const admission = record(seal(plan, planPin, \"admission\", chainArgs(\"migration\", migration)))\n    const deployment = seal(plan, planPin, \"deployment\", { ...chainArgs(\"migration\", migration), ...chainArgs(\"admission\", admission) })\n    expect(deployment.intent.prerequisiteOutcomes).toEqual([migration.outcomePin, admission.outcomePin])\n\n    const other = input(); other.observedTarget.projectRef = \"zyxwvutsrqponmlkjihg\"\n    const otherPlan = await build(other), otherPin = artifactPin(\".superpowers/m80-foundation-hosted-other-plan.json\", otherPlan)\n    expect(() => seal(otherPlan, otherPin, \"admission\", chainArgs(\"migration\", migration))).toThrow(\"predecessor\")\n    expect(() => seal(plan, planPin, \"admission\", {})).toThrow(\"chain required\")\n  })\n\n  test(\"requires post-intent authoritative observation and makes uncertainty durable\", async () => {\n    const plan = await build(input()), planPin = artifactPin(\".superpowers/m80-foundation-hosted-plan.json\", plan)\n    const sealed = seal(plan, planPin, \"migration\"), intent = sealed.intent\n    const before = observation(intent, \"definitive_success\", \"2026-09-24T22:11:59.000Z\")\n    expect(() => record(sealed, before)).toThrow(\"post-intent\")\n    const uncertain = record(sealed, observation(intent, \"unknown\"))\n    expect(uncertain.outcome).toMatchObject({ status: \"uncertain_do_not_retry\", nextActionAllowed: false })\n    expect(() => seal(plan, planPin, \"admission\", chainArgs(\"migration\", uncertain))).toThrow(\"success proof\")\n  })\n\n  test(\"does not promote unknown or failed observations by rewriting outcome status\", async () => {\n    const plan = await build(input()), planPin = artifactPin(\".superpowers/m80-foundation-hosted-plan.json\", plan)\n    for (const transport of [\"unknown\", \"definitive_failure\"] as const) {\n      const migrationSealed = seal(plan, planPin, \"migration\")\n      const forged = promoteOutcome(record(migrationSealed, observation(migrationSealed.intent, transport)))\n      expect(() => seal(plan, planPin, \"admission\", chainArgs(\"migration\", forged))).toThrow(\"success proof\")\n    }\n    const migration = record(seal(plan, planPin, \"migration\"))\n    const admissionSealed = seal(plan, planPin, \"admission\", chainArgs(\"migration\", migration))\n    const forgedAdmission = promoteOutcome(record(admissionSealed, observation(admissionSealed.intent, \"unknown\")))\n    expect(() => seal(plan, planPin, \"deployment\", { ...chainArgs(\"migration\", migration), ...chainArgs(\"admission\", forgedAdmission) })).toThrow(\"success proof\")\n  })\n\n  test(\"requires successor gates and intents to follow predecessor outcomes\", async () => {\n    const plan = await build(input()), planPin = artifactPin(\".superpowers/m80-foundation-hosted-plan.json\", plan)\n    const migration = record(seal(plan, planPin, \"migration\"))\n    const earlyTime = \"2026-09-24T22:11:59.999Z\", earlyGate = gateBundle(plan, planPin, \"admission\", earlyTime)\n    expect(() => sealM80HostedIntent({ plan, planPin, stage: \"admission\", now: NOW, ...earlyGate, ...chainArgs(\"migration\", migration) })).toThrow(\"follow the migration outcome\")\n\n    const admission = record(seal(plan, planPin, \"admission\", chainArgs(\"migration\", migration)))\n    const retimedGate = gateBundle(plan, planPin, \"admission\", earlyTime)\n    const unsignedIntent = { ...structuredClone(admission.intent), createdAt: earlyTime, gate: retimedGate.gatePin } as Record<string, unknown>\n    delete unsignedIntent.intentSha256\n    const retimedIntent = { ...unsignedIntent, intentSha256: m80HostedSha256(m80HostedCanonicalJson(unsignedIntent)) } as unknown as M80HostedIntent\n    const retimedAdmission = record({ ...retimedGate, intent: retimedIntent }, observation(retimedIntent))\n    expect(() => seal(plan, planPin, \"deployment\", { ...chainArgs(\"migration\", migration), ...chainArgs(\"admission\", retimedAdmission) })).toThrow(\"chronologically linked\")\n\n    const normalAdmission = seal(plan, planPin, \"admission\", chainArgs(\"migration\", migration))\n    const historicGate = gateBundle(plan, planPin, \"admission\", earlyTime)\n    const historicUnsignedIntent = { ...structuredClone(normalAdmission.intent), gate: historicGate.gatePin } as Record<string, unknown>\n    delete historicUnsignedIntent.intentSha256\n    const historicIntent = { ...historicUnsignedIntent, intentSha256: m80HostedSha256(m80HostedCanonicalJson(historicUnsignedIntent)) } as unknown as M80HostedIntent\n    const historicAdmission = record({ ...historicGate, intent: historicIntent }, observation(historicIntent))\n    expect(() => seal(plan, planPin, \"deployment\", { ...chainArgs(\"migration\", migration), ...chainArgs(\"admission\", historicAdmission) })).toThrow(\"predecessor gate and intent\")\n  })\n\n  test(\"uses one deterministic operation path and preserves first durable bytes\", async () => {\n    const firstPlan = await build(input()), equivalentPlan = await build(input(), new Date(NOW.getTime() + 60_000))\n    expect(equivalentPlan.planSha256).not.toBe(firstPlan.planSha256)\n    expect(m80HostedIntentPath(equivalentPlan, \"migration\")).toBe(m80HostedIntentPath(firstPlan, \"migration\"))\n    const directory = await mkdtemp(join(tmpdir(), \"m80-hosted-prep-\")); temporary.push(directory)\n    const path = join(directory, m80HostedIntentPath(firstPlan, \"migration\").split(\"/\").pop()!)\n    await writeM80HostedEvidenceOnce(path, { status: \"intent_sealed_not_executed\" })\n    const before = await readFile(path, \"utf8\")\n    await expect(writeM80HostedEvidenceOnce(path, { status: \"different\" })).rejects.toThrow(\"Never retry blindly\")\n    expect(await readFile(path, \"utf8\")).toBe(before)\n  })\n\n  test(\"does not report completion when durable sync fails and preserves the exclusive marker\", async () => {\n    const directory = await mkdtemp(join(tmpdir(), \"m80-hosted-sync-\")); temporary.push(directory)\n    const path = join(directory, \"m80-foundation-hosted-sync-failure.json\")\n    let closed = false\n    await expect(writeM80HostedEvidenceOnce(path, { status: \"intent_sealed_not_executed\" }, async target => {\n      const actual = await open(target, \"wx\")\n      return {\n        writeFile: (data, encoding) => actual.writeFile(data, encoding),\n        sync: async () => { throw new Error(\"injected sync failure\") },\n        close: async () => { await actual.close(); closed = true },\n      }\n    })).rejects.toThrow(\"injected sync failure\")\n    expect(closed).toBe(true)\n    expect(JSON.parse(await readFile(path, \"utf8\"))).toEqual({ status: \"intent_sealed_not_executed\" })\n    await expect(writeM80HostedEvidenceOnce(path, { status: \"different\" })).rejects.toThrow(\"Never retry blindly\")\n  })\n})\n"
