).join('<br>')+'</td><td data-label="Retained evidence">'+links(g.evidenceReferences)+'</td></tr>').join('')+'</tbody></table><h3>Process categories</h3><table><thead><tr><th>Category</th><th>Disposition and rationale</th><th>Retained evidence</th></tr></thead><tbody>'+a.assessments.map(x=>'<tr><td data-label="Category">'+escape(categories[x.category])+'</td><td data-label="Disposition and rationale">'+escape(states[x.disposition])+'<br>'+escape(x.reason)+(x.discoveredSourceId?'<br>Discovered source '+escape(x.discoveredSourceId):'')+'</td><td data-label="Retained evidence">'+links(x.evidenceReferences)+'</td></tr>').join('')+'</tbody></table>':'<h2>Process discovery</h2><p>No retained process discovery is available; applicability remains unresolved.</p>';return discovery+'<h2>Source method and estimate basis</h2><ul>'+s.proof.sourceVersions.map(({family,version:v})=>'<li>'+sourceLabel(v.activity.binding.sourceId)+'<br>'+escape(family==='fugitive'?'Servicing gas consumption estimate; linked prior releases are included once in the refill, not added again. Declared service evidence is not independently verified.':family==='stationary_diesel'?'Stationary diesel estimate uses default higher heating value, not measured customer fuel heat content.':family==='mobile_diesel'?'Mobile fossil-diesel candidate calculation uses dedicated annual consumption and vehicle distance.':'Natural-gas candidate calculation uses dedicated annual heat-input consumption.')+'<br>Retained source version '+escape(v.id)+'</li>').join('')+'</ul>'}
