export function parseM78Json(s:string,max=6000000):unknown{try{return parseM77Json(s,max)}catch{m78Fail('Invalid or duplicate-key Scope 1 JSON.')}}
export function validateM78ProcessSave(value:unknown):M78ProcessSaveInput {
 m78Keys(value,['profile','binding','declaration','locations','assessments','gasCoverage','evidenceStatements','manualConfirmation',...predKeys]);predecessor(value);const v=structuredClone(value) as unknown as M78ProcessSaveInput;if(v.profile!==M78_PROCESS_PROFILE)m78Fail('Process-screen profile required.');binding(v.binding);if(typeof v.manualConfirmation!=='boolean')m78Fail('Explicit confirmation required.');
 if(v.declaration!==null){const d=v.declaration;m78Keys(d,['completeness','coveredEntityIds','coveredFacilityIds','allControlledOperationsIncluded','discoveryBasis']);if(!['unknown','partial','declared_complete'].includes(d.completeness)||typeof d.allControlledOperationsIncluded!=='boolean')m78Fail('Explicit discovery status required.');d.coveredEntityIds=unique(list(d.coveredEntityIds,150).map(uuid));d.coveredFacilityIds=unique(list(d.coveredFacilityIds,150).map(uuid));m78Text(d.discoveryBasis,2000,20)}
 for(const x of list(v.locations,25)){m78Keys(x,['rowId','entityId','facilityId','operationId','businessActivities','equipmentAndMaterials','controlExplanation','evidenceReferences']);uuid(x.rowId);uuid(x.entityId);if(x.facilityId!==null)uuid(x.facilityId);if(x.operationId!==null)ident(x.operationId);if((x.facilityId===null)===(x.operationId===null))m78Fail('Location requires a retained facility or explicit non-facility operation.');m78Text(x.businessActivities);m78Text(x.equipmentAndMaterials);m78Text(x.controlExplanation);x.evidenceReferences=refs(x.evidenceReferences)}unique(v.locations.map(x=>x.rowId));v.locations.sort((a,b)=>a.rowId.localeCompare(b.rowId));
 for(const x of list(v.assessments,100)){m78Keys(x,['rowId','category','discoveredSourceId','locationRowIds','disposition','reason','evidenceReferences']);uuid(x.rowId);if(!M78_CATEGORIES.includes(x.category as any)||!['unknown','indicated','not_applicable_proposed'].includes(x.disposition as string))m78Fail('Unsupported process assessment.');if(x.discoveredSourceId!==null)ident(x.discoveredSourceId);if(x.disposition==='indicated'&&x.discoveredSourceId===null)m78Fail('Indicated sources need stable identities.');if(x.disposition!=='indicated'&&x.discoveredSourceId!==null)m78Fail('Previously indicated sources remain indicated and unsupported.');x.locationRowIds=unique(list(x.locationRowIds,25).map(uuid));if(x.reason!==null)m78Text(x.reason);x.evidenceReferences=refs(x.evidenceReferences)}unique(v.assessments.map(x=>x.rowId));unique(v.assessments.filter(x=>x.discoveredSourceId!==null).map(x=>x.discoveredSourceId!));v.assessments.sort((a,b)=>a.rowId.localeCompare(b.rowId));
 for(const x of list(v.gasCoverage,7)){m78Keys(x,['gasGroup','state','sourceIds','discoveredSourceIds','locationRowIds','reason','evidenceReferences']);if(!M78_GAS_GROUPS.includes(x.gasGroup as any)||!['unknown','indicated','not_applicable_proposed','covered_by_sources'].includes(x.state as string))m78Fail('Seven-gas applicability state required.');x.sourceIds=unique(list(x.sourceIds,150).map(uuid));x.discoveredSourceIds=unique(list(x.discoveredSourceIds,100).map(ident));x.locationRowIds=unique(list(x.locationRowIds,25).map(uuid));x.evidenceReferences=refs(x.evidenceReferences);if(x.reason!==null)m78Text(x.reason);if(x.state==='covered_by_sources'&&!(x.sourceIds as string[]).length||x.state==='indicated'&&!(x.discoveredSourceIds as string[]).length||x.state!=='indicated'&&(x.discoveredSourceIds as string[]).length||x.state==='not_applicable_proposed'&&(x.sourceIds as string[]).length)m78Fail('Gas applicability conflicts with declared sources.')}unique(v.gasCoverage.map(x=>x.gasGroup));if(v.gasCoverage.length!==7)m78Fail('All seven gas groups require explicit assessment.');v.gasCoverage.sort((a,b)=>a.gasGroup<b.gasGroup?-1:1);
 for(const x of list(v.evidenceStatements,100)){m78Keys(x,['reference','issuer','description','issuedOn','purpose','entityId','facilityId']);ident(x.reference);m78Text(x.issuer,120);m78Text(x.description,2000,20);date(x.issuedOn);if(!['business_activity','process_inspection','offsite_discovery'].includes(x.purpose as string))m78Fail('Evidence purpose required.');uuid(x.entityId);if(x.facilityId!==null)uuid(x.facilityId)}unique(v.evidenceStatements.map(x=>x.reference));v.evidenceStatements.sort((a,b)=>a.reference.localeCompare(b.reference));
 if(new TextEncoder().encode(m78CanonicalJson(v)).length>M78_MAX_ACTIVITY_BYTES)m78Fail('Process activity exceeds capacity.');return v
}
export function validateM78InventorySave(value:unknown):M78InventorySaveInput{m78Keys(value,['profile','binding','note',...predKeys]);predecessor(value);if(value.profile!==M78_INVENTORY_PROFILE)m78Fail('Inventory profile required.');binding(value.binding);m78Text(value.note,2000);return structuredClone(value) as unknown as M78InventorySaveInput}
export function validateM78Review(value:unknown):M78ReviewInput{m78Keys(value,['versionId','expectedVersionSha256','expectedDependencySha256','decision','note','acknowledgedLimitations','idempotencyKey']);uuid(value.versionId);hash(value.expectedVersionSha256);hash(value.expectedDependencySha256);uuid(value.idempotencyKey);m78Text(value.note,2000);if(!['accepted_bounded_process_screen','accepted_bounded_inventory','changes_requested'].includes(value.decision as string)||m78CanonicalJson(value.acknowledgedLimitations)!==m78CanonicalJson(M78_LIMITATIONS))m78Fail('Exact bounded review and limitations required.');return structuredClone(value) as unknown as M78ReviewInput}
