 'companyLabel',source->>'companyLabel','facilityLabel',source->>'facilityLabel','display',source#>>'{total,display}','unrounded',source#>>'{total,unrounded}','quantityKwh',source->>'quantityKwh','quantityMwh',source->>'quantityMwh',
